import type { Routing } from "fixture-server-core";

export type Handler = (request: Request, response: Response) => void;

export interface Request {
  path: string;
}

export interface Response {
  send(body: unknown): void;
}

/** An app whose members the package declares itself. */
export interface App {
  get(path: string, handler: Handler, ...more: Handler[]): this;
  post(path: string, ...handlers: Handler[]): this;
}

declare function make(): App;
export default make;

/** A router whose members come from a base package, as a framework's do. */
export interface Router extends Routing<Handler> {}
export declare function router(): Router;
